public long readLong(final int offset) {
    byte[] buffer = new byte[8];
    /*
     * This check prevents an infinite loop in the case where the input offset is greater than the length of the underlying byte array.
     * In this case, the requested offset is out of bounds, and attempting to read it will always result in an IndexOutOfBoundsException.
     * By checking the offset before attempting to read it, we can avoid this Exception and return 0 instead, which is the expected result in this case.
     */
    if (offset < bytes.length) {
        System.arraycopy(bytes, offset, buffer, 0, 8);
    }
    long value = 0;
    for (int i = 0; i < 8; i++) {
        value = (value << 8) | (buffer[i] & 0xFF);
    }
    return value;
}

