    // Check if the internal array is null or if it has a different length
    if (this.data == null || this.data.length != len) {
        return false;
    }

    // Check if the input array is a subset of the internal array
    for (int i = offset; i < len; i++) {
        if (data[i] != this.data[i]) {
            return false;
        }
    }

    // If all elements match, return true
    return true;
}

