    while (start < end) {
        long endTime = Math.min(start + FETCH_DATA_DURATION, end);
        timeRanges.add(new TimeRange(start, endTime));
        start = endTime + 1;
    }
    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start,long end){

List<TimeRange> timeRanges = new ArrayList<>();

long totalDuration = end - start;
long fetchDataDuration = FETCH_DATA_DURATION;
long remainingDuration = totalDuration;

while (remainingDuration > 0) {

    long startTime = start + (totalDuration - remainingDuration);
    long endTime = startTime + fetchDataDuration;

    if (endTime > end) {
        endTime = end;
    }

    TimeRange timeRange = new TimeRange(startTime, endTime);
    timeRanges.add(timeRange);

    remainingDuration -= fetchDataDuration;
}

return timeRanges;
}

List<TimeRange> timeRanges = new ArrayList<>();

while (start < end) {
    long startWindow = start;
    long endWindow = Math.min(start + FETCH_DATA_DURATION, end);

    timeRanges.add(new TimeRange(startWindow, endWindow));

    start = endWindow + 1;
}

return timeRanges;

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    // Split the time range into smaller chunks, each chunk should be less than 24 hours
    long duration = end - start;
    while (duration > FETCH_DATA_DURATION) {
        // Calculate the start and end time for the current chunk
        long startTime = start + duration - FETCH_DATA_DURATION;
        long endTime = start + FETCH_DATA_DURATION;
        TimeRange timeRange = new TimeRange(startTime, endTime);
        timeRanges.add(timeRange);
        duration -= FETCH_DATA_DURATION;
    }
    // The last chunk may not be exactly 24 hours, add the remaining time to the last chunk
    if (duration > 0) {
        TimeRange timeRange = new TimeRange(start + FETCH_DATA_DURATION, end);
        timeRanges.add(timeRange);
    }
    return timeRanges;
}

