static long compressTimeBucket(long timeBucket, int dayStep) {
    int year = (int) (timeBucket / 100000000);
    int month = (int) ((timeBucket - year * 100000000) / 1000000);
    int day = (int) ((timeBucket - year * 100000000 - month * 1000000) / 10000);
    int hour = (int) ((timeBucket - year * 100000000 - month * 1000000 - day * 10000) / 100);
    int minute = (int) ((timeBucket - year * 100000000 - month * 1000000 - day * 10000 - hour * 100) / 1);
    if (dayStep == 1) {
        return year * 100000000 + month * 1000000 + day * 10000 + hour * 100 + minute;
    } else if (dayStep == 7) {
        return year * 100000000 + month * 1000000 + (day / 7) * 10000 + hour * 100 + minute;
    } else {
        return timeBucket;
    }
}

