    long compressedTimeBucket = 0L;

    // Get the year and day of the week from the timeBucket
    int year = (int) ((timeBucket / 1_000_000L) / 100L);
    int dayOfWeek = (int) (timeBucket % 1_000_000L) / 100L;

    // Calculate the new year and day of the week based on the dayStep
    int newYear = year - (dayOfWeek - 1) / dayStep * dayStep;
    int newDayOfWeek = dayOfWeek - (dayOfWeek - 1) % dayStep;

    // Check if the new year is negative
    if (newYear < 0) {
        // Add 100 to the new year to ensure it is positive
        newYear += 100;

        // Add 7 to the new day of the week to ensure it is positive
        newDayOfWeek += 7;
    }

    // Calculate the new timeBucket value
    compressedTimeBucket = (long) (newYear * 1_000_000L + newDayOfWeek * 100L);

    // Return the compressed timeBucket value
    return compressedTimeBucket;
