        int year = (int) (timeBucket / 10000);
        int month = (int) ((timeBucket % 10000) / 100);
        int day = (int) (timeBucket % 100);
        // Find the first day of the month
        int firstDayOfMonth = 1;
        if (month == 1 || month == 3 || month == 5 || month == 7 || month == 8 || month == 10 || month == 12) {
            firstDayOfMonth = 1;
        } else if (month == 4 || month == 6 || month == 9 || month == 11) {
            firstDayOfMonth = 15;
        }
        // Calculate the number of months since the first day of the month
        int monthsSinceFirstOfMonth = (day - firstDayOfMonth + dayStep - 1) / dayStep;
        int daysSinceFirstOfMonth = (monthsSinceFirstOfMonth * dayStep) - (firstDayOfMonth - day);
        // Reconstruct the new time bucket
        newTimeBucket = year * 10000 + month * 100 + daysSinceFirstOfMonth;
    }
    return newTimeBucket;
