public static int computeUTF8Size(CharSequence str, int index, int len) {
    final int strLength = str.length();
    int size = 0;
    for (int i = index; i < index + len && i < strLength; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7f) {
            size++;
        } else if (ch <= 0x7ff) {
            size += 2;
        } else if (Character.isHighSurrogate(ch)) {
            ++i;
            size += 4;
        } else {
            size += 3;
        }
    }
    return size;
}

public static int computeUTF8Size(CharSequence str, int index, int len) {
    // Initialize the size of the UTF8 string to 0
    int size = 0;

    // Loop through the provided index and length
    for (int i = index; i < len; i++) {
        // Get the current character at the index
        char c = str.charAt(i);

        // If the character is a high surrogate, increment the size by 4,
        // since it will be represented by a 4-byte UTF8 sequence
        if (Character.isHighSurrogate(c)) {
            size += 4;
        }

        // If the character is a low surrogate, increment the size by 3,
        // since it will be represented by a 3-byte UTF8 sequence
        else if (Character.isLowSurrogate(c)) {
            size += 3;
        }

        // For all other characters, increment the size by 1,
        // since they will be represented by a single-byte UTF8 sequence
        else {
            size += 1;
        }
    }

    // Return the computed size of the UTF8 string
