    // Split the path component of the URI into segments
    List<String> segments = Arrays.asList(u.getPath().split("/"));

    // Create a new list to store the decoded path segments
    List<PathSegmentImpl> decodedSegments = new ArrayList<>();

    // Loop through each segment and decode it if specified
    for (String segment : segments) {
        // Decode the segment if necessary
        String decodedSegment;
        if (decode) {
            decodedSegment = URLDecoder.decode(segment, "UTF-8");
        } else {
            decodedSegment = segment;
        }

        // Create a new path segment and add it to the list
        PathSegmentImpl pathSegment = new PathSegmentImpl(decodedSegment);
        decodedSegments.add(pathSegment);
    }

    // Return the list of decoded path segments
    return decodedSegments;
}

