    for (String pathComponent : pathComponents) {
        if (pathComponent.isEmpty()) {
            continue;
        }

        if (decode) {
            pathComponent = URLDecoder.decode(pathComponent, "UTF-8");
        }

        segments.add(new PathSegmentImpl(pathComponent));
    }

    return segments;
}

static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    // Check if the path component of the URI is an absolute path component
    if (u.getRawPath().startsWith("/")) {
        // If so, skip the leading '/' and start decoding the path segments
        int start = 1;
        int end = u.getRawPath().indexOf("/", start);
        while (end != -1) {
            // Decode the path segment and add it to the list
            PathSegmentImpl segment = new PathSegmentImpl(u.getRawPath().substring(start, end));
            if (decode) {
                segment = segment.decode();
            }
            start = end + 1;
            end = u.getRawPath().indexOf("/", start);
            result.add(segment);
        }
    } else {
        // Decode the path segments and add them to the list
        int end = u.getRawPath().indexOf("/");
        while (end != -1) {
            PathSegmentImpl segment = new PathSegmentImpl(u.getRawPath().substring(0, end));
            if (decode) {
                segment = segment.decode();
            }
            result.add(segment);
            end = u.getRawPath().indexOf("/", end + 1);
        }
    }
    return result;
}

