totalSize += node.Word.ByteSize;
}
break;
case NODE:
out.writeBoolean(node.Child != null);
totalSize += 1;
if (node.Child != null) {
out.writeBoolean(node.Child.Type);
totalSize += 1;
writeTo(out, node.Child);
}
break;
case QUOTE:
out.writeBoolean(node.Quote != null);
totalSize += 1;
if (node.Quote != null) {
out.writeInt(node.Quote.Length);
totalSize += 4;
out.writeByte(node.Quote.Index);
totalSize += 1;
}
break;
}
return totalSize;
}

