public static int nextPrime(int desiredCapacity) {

  // The desired capacity cannot be < 0.
  if(desiredCapacity < 0) {
    throw new IllegalArgumentException("desiredCapacity must be >= 0, but is: " + desiredCapacity);
  }

  // Special case: if the desired capacity is 0, return a prime number.
  if(desiredCapacity == 0) {
    return 7;
  }

  // Start with the next prime number after the desired capacity.
  int primeCandidate = (desiredCapacity % 2 == 0) ? desiredCapacity + 1 : desiredCapacity;

  // Keep incrementing by 2 until the prime candidate is >= the desired capacity.
  while(primeCandidate < desiredCapacity) {
    primeCandidate += 2;
  }

  // At this point, the prime candidate is guaranteed to be >= the desired capacity. Check if it's prime.
  boolean isPrime = false;
  for(int lessThanOrEqualToNumber = 2; lessThanOrEqualToNumber * lessThanOrEqualToNumber <= primeCandidate; lessThanOrEqualToNumber++) {
    if(primeCandidate % lessThanOrEqualToNumber == 0) {
      isPrime = true;
      break;
    }
  }

  // If the prime candidate is not prime, increment by 2 to get the first larger prime number.
  if(!isPrime) {
    primeCandidate += 2;
  }

  return primeCandidate;
}

