public static int nextPrime(int desiredCapacity){
    if (desiredCapacity >= 1000) {
        // If the input capacity is greater than or equal to 1000, we want a capacity which is close to the input, but not exactly equal to it.
        // We aim for a capacity which is within 11% of the input.
        desiredCapacity = Math.max(11, Math.round(desiredCapacity * 0.11f));
    } else {
        // If the input capacity is less than 1000, we want a capacity which is a power of 2, which should be very fast for hashtables.
        // First, we find the nearest power of 2 to the input capacity.
        desiredCapacity--;
        desiredCapacity |= desiredCapacity >> 1;
        desiredCapacity |= desiredCapacity >> 2;
        desiredCapacity |= desiredCapacity >> 4;
        desiredCapacity |= desiredCapacity >> 8;
        desiredCapacity |= desiredCapacity >> 16;
        desiredCapacity++;
    }
    // Now we check if the input capacity is prime
    if (isPrime(desiredCapacity)) {
        return desiredCapacity;
    }
    // If the input capacity is not prime, we find the nearest prime number by incrementing or decrementing until we find a prime number.
    while (true) {
        if (isPrime(desiredCapacity + 1)) {
            return desiredCapacity + 1;
        }
        if (isPrime(desiredCapacity - 1)) {
            return desiredCapacity - 1;
        }
        desiredCapacity++;
    }
