public static int nextPrime(int desiredCapacity) {
    // basic case: the input parameter is already a prime
    if (desiredCapacity % 2 == 0) {
        if (desiredCapacity == 2) {
            return desiredCapacity;
        } else {
            return desiredCapacity + 1;
        }
    }

    // find the closest prime number
    int prime = desiredCapacity - 1;
    while (!isPrime(prime)) {
        prime++;
    }
    return prime;
}

public static boolean isPrime(int number) {
    // trivial case: 1 is not prime
    if (number <= 1) {
        return false;
    }

    // check if the number is even
    if (number % 2 == 0) {
        // even numbers are not prime
        return false;
    }

    // check if the number is a multiple of 3
    if (number % 3 == 0) {
        // numbers that are multiples of 3 are not prime
        return false;
    }

    // the number is probably prime
    return true;
}

