  }
}

private void ensureBufferCapacity(int limit) {

  // Calculate the new buffer capacity
  int newCapacity = limit + BUFFER_SIZE;

  // Check if there is already enough capacity
  if (newCapacity <= buffer.capacity()) {
    return;
  }

  // Create a new buffer with the new capacity
  ByteBuffer newBuffer = ByteBuffer.allocateDirect(newCapacity);

  // Move the existing data to the new buffer
  int oldPosition = buffer.position();
  buffer.position(0);
  buffer.limit(oldPosition);
  newBuffer.put(buffer);
  newBuffer.flip();
  buffer = newBuffer;
}

