public GraphPath<V, E> edgeSetToGraphPath(Set<E> tour, Graph<V, E> graph) {
    // Initialize the graph path with the first edge in the tour
    GraphPath<V, E> path = new GraphPath<V, E>(graph, tour.iterator().next());

    // Iterate over the remaining edges in the tour and add them to the graph path
    for (E edge : tour) {
        path.addEdge(edge);
    }

    return path;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<V> vertices = new ArrayList<>();
    for (E edge : tour) {
        vertices.add(graph.getEdgeSource(edge));
        vertices.add(graph.getEdgeTarget(edge));
    }
    return new GraphPathImpl<>(graph, vertices, new LinkedList<>());
}

private static GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour.isEmpty()) {
        return null;
    }
    GraphPath<V, E> path = new GraphPath<>(graph);
    Iterator<E> iterator = tour.iterator();
    E firstEdge = iterator.next();
    path.addEdge(firstEdge);
    E currentEdge = firstEdge;
    while (iterator.hasNext()) {
        E nextEdge = iterator.next();
        if (!graph.areAdjacent(currentEdge, nextEdge)) {
            throw new IllegalArgumentException("Edges in the tour must be adjacent.");
        }
        path.addEdge(nextEdge);
        currentEdge = nextEdge;
    }
    return path;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    // Initialize the graph path
    GraphPath<V,E> path = new GraphPath<V,E>(graph);

    // Iterate over the edges in the set
    for (E edge : tour) {
        // Get the endpoint vertices
        V start = graph.getEdgeStart(edge);
        V end = graph.getEdgeEnd(edge);

        // Add the edge to the path
        path.addEdge(edge);

        // Set the endpoint vertex as the current vertex
        path.setCurrentVertex(end);
    }

    // Return the path
    return path;
}

