public int addConstantNameAndType(String name, String descriptor) {
    // Check if the constant pool already contains a similar item
    ConstantInfo constant = getConstant(name, descriptor);
    if (constant != null) {
        return constant.getIndex();
    }

    // Create a new CONSTANT_NameAndType_info object
    ConstantNameAndTypeInfo nameAndType = new ConstantNameAndTypeInfo();
    nameAndType.setName(name);
    nameAndType.setDescriptor(descriptor);

    // Add the new item to the constant pool
    constant = addConstant(nameAndType);

    // Return the index of the new item
    return constant.getIndex();
}

int function (final String name, final String descriptor) {

    if (name == null || descriptor == null) {
        throw new NullPointerException("Null arguments");
    }

    // Search for an existing constant pool entry
    for (ClassFile.ConstantInfo info: constantPool) {
        if (info instanceof ClassFile.ConstantNameAndTypeInfo) {
            ClassFile.ConstantNameAndTypeInfo existingInfo = (ClassFile.ConstantNameAndTypeInfo) info;
            if (name.equals(existingInfo.getName()) && descriptor.equals(existingInfo.getDescriptor())) {
                return existingInfo;
            }
        }
    }

    // Create a new constant pool entry if it does not exist
    ClassFile.ConstantNameAndTypeInfo newInfo = new ClassFile.ConstantNameAndTypeInfo(name, descriptor);
    constantPool.add(newInfo);
    return newInfo;
}

