                    int maximum = model.getMaximum();
                    int minimum = model.getMinimum();

                    // Calculate the new value for the vertical scrollbar
                    int newValue = row * maximum / extent;

                    // Set the new value for the vertical scrollbar
                    vertical.setValue(newValue);
