public static String encodeTemplateNames(String s) {

    // Use a StringBuilder to build the encoded string
    StringBuilder sb = new StringBuilder();

    // Iterate over the characters in the input string
    for (char c : s.toCharArray()) {
        // If the current character is '{', replace it with '%7B'
        if (c == '{') {
            sb.append("%7B");
        }
        // If the current character is '}', replace it with '%7D'
        else if (c == '}') {
            sb.append("%7D");
        }
        // Otherwise, append the character as is
        else {
            sb.append(c);
        }
    }

    // Return the encoded string
    return sb.toString();
}

private static String encodeTemplateNames(String s) {
    // Split the string at the characters '{' and '}'
    String[] splitted = s.split("(?<={)|(?=})");
    // Iterate through the splitted string and encode the characters
    StringBuilder builder = new StringBuilder();
    for (String part : splitted) {
        builder.append(URLEncoder.encode(part, "UTF-8"));
    }
    return builder.toString();
}

